CREATE INDEX idx_users_upper_name ON users (UPPER(name));
-- или
CREATE INDEX idx_users_name_lower ON users (LOWER(name));
-- или использовать оператор ILIKE вместо UPPER() как в переписанном запросе.

CREATE INDEX idx_users_name_lower ON users (lower(name));
CREATE INDEX idx_users_email_lower ON users (lower(email));

-- Используйте ILIKE вместо LIKE для регистронезависимого сравнения

CREATE INDEX idx_users_name_gin ON users USING GIN (name gin_trgm_ops);
CREATE INDEX idx_users_name_gist ON users USING GiST (name gist_trgm_ops); -- Выберите один из подходящих типов индексов в зависимости от объема данных и нагрузки
-- Также потребуется установить расширение pg_trgm: CREATE EXTENSION IF NOT EXISTS pg_trgm;

SELECT установить расширение pg_trgm и использовать функцию to_tsvector:
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Добавить поле с текстовым представлением
ALTER TABLE users ADD COLUMN name_tsvector TSVECTOR;
UPDATE users SET name_tsvector = to_tsvector('simple', name);
CREATE INDEX idx_users_name_tsvector ON users USING GIN (name_tsvector);

-- Переписать запрос
UPDATE users SET last_login = NOW() WHERE name_tsvector @@ to_tsquery('simple', 'John');

